window.SITE.handouts.push(
 /* ================= WEEK 3 · PART 1 ================= */
 {n:5, wk:3, title:"Zeus, Hera, Poseidon, and Apollo", sub:"The divine family, the loves of Zeus, and the god of Delphi",
  overview:{img:"h5_gossaert", cap:["Jan Gossaert","Neptune and Amphitrite","1516"],
   sum:"The Greeks imagined their gods as a family that looks and behaves like a human one, only immortal and far more powerful. Zeus is the father who keeps order, Hera the mother who guards marriage, and their brothers and children each control part of the world. Most stories about Zeus are about his unions with goddesses and mortal women, which produce the forces of the universe and the heroes of legend. Apollo, his son by Leto, stands for prophecy, music, healing, and order.",
   bul:["Gods as an immortal human family","Zeus’s unions create cosmic powers and heroes","Apollo: prophecy, music, healing, plague"],
   terms:[["Anthropomorphism","Picturing gods in human form with human feelings; the basis of nearly all Greek religious art."],["Xenia","Guest-friendship, the sacred duty between host and guest that Zeus protects; breaking it brings disaster."],["Metis","Titaness of cleverness, Zeus’s first consort, mother of Athena."],["Themis","Titaness of divine law and order; by Zeus mother of the Horae (Seasons) and the Moirae (Fates)."],["Moirae (Fates)","Clotho, who spins the thread of life; Lachesis, who measures it; and Atropos, who cuts it."],["Eurynome","An Oceanid, by Zeus mother of the three Graces."],["Mnemosyne","Titaness of memory, by Zeus mother of the nine Muses."]]},
  slides:[
  {type:"work", key:"h5_ingres", artist:"Jean-Auguste-Dominique Ingres", title:"Jupiter and Thetis", date:"1811", det:"Oil on canvas · Musée Granet, Aix-en-Provence",
   fn:"A required showpiece Ingres sent from Rome to the French Academy as a prize student; it was bought by the French state.",
   sum:"The sea goddess Thetis kneels and touches Zeus’s chin, the ancient gesture of a suppliant, begging him to honor her son Achilles, as in the first book of the Iliad. Zeus sits enthroned like an ancient cult statue, with his eagle and scepter, while the jealous Hera watches from the upper left. Ingres turns the king of the gods into an image of absolute, almost frightening authority.",
   bul:["Scene from Iliad 1: Thetis pleads for Achilles","Zeus as enthroned cult image","Hera watches from the clouds"], terms:[]},
  {type:"theme", title:"A family of gods", img:"h5_hesperides", stmt:"Greek gods quarrel, love, and scheme like a human family.",
   para:"Each Olympian has a family role and a part of the world: Zeus the father and judge, Hera the wife and mother, Poseidon the sea, Hestia the hearth, Demeter the harvest, Hephaestus the crafts, Athena women’s skills and practical wisdom, Aphrodite desire, Apollo prophecy and healing, Hermes travel and messages. Because the gods act like people, their stories could model, or warn against, human behavior.",
   bul:["Each god has a domain and a family role","Human passions on a cosmic scale","Myths as models and warnings"],
   terms:[], works:["h5_ingres","h5_hesperides","h5_gossaert"]},
  {type:"work", key:"h5_danae", artist:"Titian", title:"Danaë", date:"ca. 1560–65", det:"Oil on canvas · Museo del Prado, Madrid",
   fn:"A later version of the Danaë Titian sent to King Philip II of Spain in 1553 (now in the Wellington Collection, London); the first owner of this one is unknown.",
   sum:"King Acrisius of Argos locked his daughter Danaë in a bronze chamber because an oracle said her son would kill him. Zeus reached her as a shower of gold, and she gave birth to the hero Perseus. Titian contrasts the relaxed, glowing princess with her old nurse, who greedily catches the coins in her apron.",
   bul:["Zeus as a shower of gold","Mother of Perseus","Later version of Philip II’s Danaë"],
   terms:[["Danaë","Argive princess imprisoned by her father; by Zeus mother of Perseus."]]},
  {type:"work", key:"h5_leda", artist:"Attributed to Francesco Melzi, after Leonardo da Vinci", title:"Leda and the Swan", date:"ca. 1505–07", det:"Oil on panel · Uffizi Gallery, Florence · copy of Leonardo’s lost original",
   fn:"A copy by Leonardo’s pupil of a lost painting that was famous in its own time; copies spread the composition across Europe.",
   sum:"Zeus took the form of a swan to seduce Leda, queen of Sparta. From the eggs she laid came Helen, later of Troy, and in most versions her sister Clytemnestra and the twins Castor and Pollux. Leonardo’s original is lost, so copies like this one preserve his twisting standing figure and the children hatching at her feet.",
   bul:["Zeus as a swan","Leda, queen of Sparta","Eggs hatch Helen and her siblings"],
   terms:[["Leda","Queen of Sparta who, after Zeus visited her as a swan, bore Helen and the Dioscuri (Castor and Pollux)."]]},
  {type:"work", key:"h5_europa", artist:"Titian", title:"The Rape of Europa", date:"1560–62", det:"Oil on canvas · Isabella Stewart Gardner Museum, Boston",
   fn:"The last of the poesie painted for Philip II of Spain.",
   sum:"Zeus turned himself into a beautiful white bull, coaxed the Phoenician princess Europa onto his back, and swam with her across the sea to Crete. There she bore Minos, the future king of Crete, whose palace and Labyrinth return in the story of Theseus. Titian shows her sprawled and terrified as the shore recedes, with cupids riding the waves.",
   bul:["Zeus as a white bull","Europa carried to Crete","Mother of King Minos"],
   terms:[["Europa","Phoenician princess carried off by Zeus in bull form; mother of Minos and namesake of Europe."]]},
  {type:"work", key:"h5_ganymede", artist:"Correggio", title:"The Abduction of Ganymede", date:"ca. 1531–32", det:"Oil on canvas · Kunsthistorisches Museum, Vienna",
   fn:"Part of a series on the Loves of Jupiter, probably made for Federico II Gonzaga, Duke of Mantua.",
   sum:"Zeus, in the form of an eagle, snatched up the beautiful Trojan prince Ganymede and carried him to Olympus to be the gods’ cupbearer. Correggio paints the boy rising into the sky while his dog barks below. The Romans called him Catamitus, the source of the English word “catamite,” because the story was read as Zeus’s love for a youth.",
   bul:["Zeus as an eagle","Trojan prince made cupbearer of the gods","Series on the Loves of Jupiter"],
   terms:[["Ganymede (Catamitus)","Trojan prince taken to Olympus by Zeus’s eagle to serve as cupbearer; Catamitus is his Latin name."]]},
  {type:"work", key:"h5_io", artist:"Correggio", title:"Jupiter and Io", date:"ca. 1531–32", det:"Oil on canvas · Kunsthistorisches Museum, Vienna",
   fn:"Companion to the Ganymede in the same Loves of Jupiter series for the Gonzaga court.",
   sum:"To hide his affair with the priestess Io from Hera, Zeus wrapped himself in a dark cloud; Correggio shows only a faint face and a hand emerging from the mist as Io melts into his embrace. When Hera grew suspicious, Zeus turned Io into a white cow, and Hera set the hundred-eyed giant Argus to guard her.",
   bul:["Zeus disguised as a cloud","Io turned into a cow","Hera sets Argus to guard her"],
   terms:[["Io","Priestess of Hera loved by Zeus and turned into a cow; she wandered as far as Egypt before regaining her form."]]},
  {type:"work", key:"h5_argus", artist:"Diego Velázquez", title:"Mercury and Argus", date:"ca. 1659", det:"Oil on canvas · Museo del Prado, Madrid",
   fn:"Painted for the Hall of Mirrors in the royal palace (Alcázar) of Madrid, a long, high room that explains the painting’s wide format.",
   sum:"Zeus sent Hermes to free Io. Hermes lulled the watchman Argus Panoptes (“all-seeing”) to sleep with music and stories, then killed him. Hera placed Argus’s hundred eyes on the tail of her peacock. Velázquez paints a quiet, shadowy moment as Hermes creeps toward the dozing guard, with the cow behind them.",
   bul:["Hermes lulls Argus to sleep","Argus’s eyes end up on the peacock","Late work by Velázquez"],
   terms:[["Argus Panoptes","Hundred-eyed giant Hera set to guard Io, killed by Hermes; his eyes decorate Hera’s peacock."]]},
  {type:"theme", title:"The loves of Zeus", img:"h5_europa", stmt:"Zeus’s many unions explain where heroes and ruling families came from.",
   para:"Zeus takes shape after shape, a shower of gold, a swan, a bull, an eagle, a cloud, to reach the women and youths he desires. To ancient audiences these stories gave great families and cities a divine ancestor: Perseus, Helen, and Minos all descend from such unions. Renaissance rulers commissioned these scenes as elegant, erotic pictures, which is why so many survive.",
   bul:["Disguises: gold, swan, bull, eagle, cloud","Divine ancestors for heroes and kings","Favorite subject of Renaissance patrons"],
   terms:[], works:["h5_danae","h5_leda","h5_europa","h5_ganymede","h5_io"]},
  {type:"work", key:"h5_hesperides", artist:"Frederic Leighton", title:"The Garden of the Hesperides", date:"1892", det:"Oil on canvas · Lady Lever Art Gallery, Port Sunlight",
   fn:"A round exhibition painting shown at the Royal Academy, made for wealthy Victorian collectors.",
   sum:"When Hera married Zeus, Earth gave her a tree of golden apples, which grew in a garden at the western edge of the world. The nymphs called the Hesperides tended it, guarded by the serpent Ladon, near where Atlas holds up the sky. Leighton’s drowsy nymphs and coiled serpent prepare for the later labor in which Heracles takes the apples.",
   bul:["Golden apples: Earth’s wedding gift to Hera","Guarded by the Hesperides and Ladon","Later stolen in a labor of Heracles"],
   terms:[["Hera’s children","With Zeus, Hebe (youth), Eileithyia (childbirth), and Ares; in Hesiod she bears Hephaestus on her own."],["Ladon","The serpent that coils around the tree of golden apples."]]},
  {type:"work", key:"h5_gossaert", artist:"Jan Gossaert", title:"Neptune and Amphitrite", date:"1516", det:"Oil on panel · Gemäldegalerie, Berlin",
   fn:"Painted for Philip of Burgundy, an admiral and later bishop, for his castle at Souburg; one of the first large mythological nudes in Northern art.",
   sum:"Poseidon, the Roman Neptune, married the sea nymph Amphitrite, and their son was the merman Triton. Gossaert, who had just seen ancient sculpture in Rome, poses the couple as massive classical nudes inside an ornate temple. Poseidon also fathered monsters and marvels: the Cyclops Polyphemus with the nymph Thoosa, and, with Medusa, the winged horse Pegasus and the warrior Chrysaor.",
   bul:["Poseidon marries Amphitrite; son Triton","Northern artist responds to ancient Rome","Father of Polyphemus and Pegasus"],
   terms:[["Amphitrite","Sea nymph, wife of Poseidon and mother of Triton."],["Pegasus and Chrysaor","Offspring of Poseidon and Medusa, born from her neck when Perseus beheaded her; Bellerophon later tamed Pegasus."],["Hades","Brother of Zeus who rules the dead with Persephone; the Cyclopes gave him a helmet of invisibility."]]},
  {type:"work", key:"h5_redon", artist:"Odilon Redon", title:"The Cyclops", date:"ca. 1914", det:"Oil on cardboard mounted on panel · Kröller-Müller Museum, Otterlo",
   fn:"A late Symbolist painting, made for collectors of Redon’s dreamlike work.",
   sum:"Polyphemus, son of Poseidon and the nymph Thoosa, is the one-eyed giant Odysseus later blinds. In a story told by Theocritus and Ovid, he falls hopelessly in love with the sea nymph Galatea. Redon shows the giant peering shyly over a hill at the sleeping nymph, turning a monster into a lonely, almost gentle figure.",
   bul:["Polyphemus, son of Poseidon","In love with Galatea","Symbolist dream image"],
   terms:[["Polyphemus","One-eyed Cyclops, son of Poseidon, who traps and is blinded by Odysseus."]]},
  {type:"work", key:"h5_pythia", artist:"Attributed to the Kodros Painter", title:"Cup with King Aegeus consulting the oracle", date:"Athenian, ca. 440–430 BCE", det:"Red-figure kylix · Altes Museum, Berlin",
   fn:"A drinking cup; it is the only surviving image from Classical Athens of the Delphic oracle at work.",
   sum:"The Athenian king Aegeus, childless, asks the oracle what to do; the answer will lead to the birth of Theseus. The prophetess, labeled Themis here, sits on Apollo’s tall tripod holding a laurel sprig and a dish. At Delphi the priestess called the Pythia spoke Apollo’s answers, and priests turned them into verse.",
   bul:["Only Classical image of the Delphic oracle","Prophetess on Apollo’s tripod with laurel","Aegeus asks about an heir"],
   terms:[["Pythia","The priestess of Apollo at Delphi who spoke his prophecies, seated on a tripod."],["Dactylic hexameter","The six-beat meter of epic poetry, in which Delphic answers were often delivered."]]},
  {type:"work", key:"h5_delphi", artist:"", title:"Temple of Apollo at Delphi", date:"4th century BCE (rebuilt after 373 BCE)", det:"Limestone · Delphi, Greece, on the slopes of Mount Parnassus",
   fn:"The home of Apollo’s oracle, the most important in the Greek world, consulted by cities and individuals before major decisions.",
   sum:"Apollo was born on the island of Delos to the Titaness Leto, after Hera banned every land from receiving her and held back the birth goddess Eileithyia. As a young god he killed the serpent Python at Delphi and took over the site. His temple carried two famous mottoes, “Know yourself” and “Nothing in excess.” Anyone stained by bloodshed had to be purified before approaching him.",
   bul:["Apollo born on Delos","Kills the Python and claims Delphi","Mottoes: know yourself; nothing in excess"],
   terms:[["Delphi","Sanctuary of Apollo on Mount Parnassus, thought to be the center (navel) of the world."],["Python","The serpent Apollo killed to take Delphi; the Pythia and the Pythian Games are named for it."],["Telphusa","A spring nymph who tried to steer Apollo away from Delphi; he buried her spring in punishment."],["Tityus","A giant who attacked Leto and was killed by Apollo and Artemis, then punished in the underworld."],["Miasma","Ritual pollution, especially from bloodshed, that Apollo’s rites could cleanse."]]},
  {type:"work", key:"h5_bernini", artist:"Piero del Pollaiuolo", title:"Apollo and Daphne", date:"ca. 1470–80", det:"Oil on wood · National Gallery, London",
   fn:"A small panel made for a private room in Florence, where mythological scenes decorated furniture and walls of wealthy homes.",
   sum:"Struck by one of Cupid’s arrows, Apollo chased the nymph Daphne, who prayed to escape and was turned into a laurel tree. Pollaiuolo dresses Apollo as a young Florentine and sets the chase in the Arno valley; he catches her just as her arms sprout into great branches of laurel. Apollo made the laurel his sacred plant, which is why winners and poets were crowned with laurel, and why we still say “laureate.”",
   bul:["Daphne becomes a laurel","Ancient myth in a Florentine landscape","Origin of “laureate”"],
   terms:[["Daphne","A nymph turned into a laurel (daphne in Greek) to escape Apollo."]]},
  {type:"work", key:"h5_hyacinth", artist:"Giovanni Battista Tiepolo", title:"The Death of Hyacinthus", date:"1752–53", det:"Oil on canvas · Thyssen-Bornemisza Museum, Madrid",
   fn:"Painted during Tiepolo’s stay in Würzburg; it belonged to Wilhelm Friedrich of Schaumburg-Lippe, who may have bought it directly from the artist.",
   sum:"Apollo loved the Spartan youth Hyacinthus and accidentally killed him with a thrown discus; from his blood grew the hyacinth flower. Tiepolo updates the story by replacing the discus with a tennis ball and racket at the youth’s feet. Apollo’s loves almost always end in loss: Cassandra rejects him, Coronis betrays him, Daphne flees.",
   bul:["Killed by Apollo’s discus","Blood becomes the hyacinth","Tiepolo swaps in a tennis racket"],
   terms:[["Cassandra","Trojan princess given prophecy by Apollo and then cursed never to be believed."],["Cumaean Sibyl","Apollo’s prophetess at Cumae in Italy, who later guides Aeneas to the underworld."],["Coronis and Asclepius","Coronis bore Apollo’s son Asclepius, god of medicine, who was raised by the centaur Chiron."],["Hygieia","Daughter of Asclepius, goddess of health, source of the word “hygiene.”"]]},
  {type:"work", key:"h5_marsyas", artist:"Titian", title:"The Flaying of Marsyas", date:"ca. 1570–76", det:"Oil on canvas · Archdiocesan Museum, Kroměříž",
   fn:"One of Titian’s last paintings, apparently kept in his studio and not made for a known patron.",
   sum:"The satyr Marsyas dared to challenge Apollo to a music contest, his pipes against the god’s lyre. He lost, and Apollo had him hung upside down and skinned alive. Titian’s loose, smeared brushwork makes the scene even more disturbing, while King Midas sits in thought nearby. The story warns against hubris, the human or near-human pride that challenges a god.",
   bul:["Music contest: pipes vs. lyre","Punishment for challenging a god","Titian’s late, loose brushwork"],
   terms:[["Marsyas","A satyr who challenged Apollo to a music contest and was flayed for losing."],["Hubris","Arrogant pride that oversteps human limits and provokes the gods."]]},
  {type:"theme", title:"Apollo: order and its price", img:"h5_pythia", stmt:"The god of reason and harmony can also be the cruelest of the gods.",
   para:"Apollo stands for light, music, prophecy, and the rule of measure, the values written on his temple. Yet his myths are full of violence: he kills the Python, flays Marsyas, and sends plague on those who offend him. For the Greeks, order and danger came from the same god, and respecting the limits he set was a matter of survival.",
   bul:["Light, music, prophecy, healing","Also plague and punishment","Know your limits: the Delphic lesson"],
   terms:[], works:["h5_pythia","h5_delphi","h5_bernini","h5_marsyas"]}
  ]},

 /* ================= WEEK 3 · PART 2 ================= */
 {n:6, wk:3, title:"Hermes, Hephaestus, Ares, and the Goddesses", sub:"Messengers, makers, lovers, and the powers of women",
  overview:{img:"h6_milo", cap:["","Aphrodite of Melos (Venus de Milo)","ca. 150–125 BCE"],
   sum:"This part covers the remaining gods and the five great goddesses. Hermes moves between worlds as messenger, trickster, and guide of the dead; Hephaestus makes things; Ares brings violence. The goddesses each govern part of women’s lives and the fertility of the world: Demeter the crops, Hestia the house, Aphrodite attraction, Artemis wild animals and girls, Athena weaving and skill.",
   bul:["Hermes: boundaries, trade, the dead","Hephaestus and Ares: craft and violence","Goddesses mapped onto women’s lives"],
   terms:[["Female Olympians and fertility","Each goddess oversees one kind of growth or plenty: Demeter the grain harvest, Hestia the household, Aphrodite sexual desire, Artemis wild animals, and Athena weaving and other crafts."]]},
  slides:[
  {type:"work", key:"h6_herm", artist:"After Alkamenes", title:"Miniature herm of Hermes", date:"Roman, 1st–2nd century CE, after a Greek original of ca. 430 BCE", det:"Marble, 4.6 cm (1¾ in.) high · Metropolitan Museum of Art, New York",
   fn:"A tiny Roman copy of a herm, the square pillar with a god’s head and male genitals that Greeks set up at doorways, crossroads, and boundaries to protect them.",
   sum:"Hermes, son of Zeus and the nymph Maia, protects travelers, merchants, and thieves, and guides souls of the dead to the underworld. Greeks set up herms, pillars topped with his bearded head, outside houses and at crossroads to ward off harm. This old-fashioned, bearded style copies a famous herm by the sculptor Alkamenes that stood at the entrance to the Athenian Acropolis.",
   bul:["Herm = boundary pillar with Hermes’s head","Protects doors, roads, and crossings","Guide of souls (psychopompos)"],
   terms:[["Herm","A square stone pillar topped with a head of Hermes, set at boundaries and doorways."],["Apotropaion","An object meant to turn away evil, such as a herm or a Gorgon’s face."],["Psychopompos","“Guide of souls,” Hermes’s role leading the dead to Hades."],["Caduceus","Hermes’s herald’s staff entwined with two snakes; one story links it to snakes the seer Tiresias struck apart."],["Autolycus","Son of Hermes, master thief, and grandfather of Odysseus."]]},
  {type:"work", key:"h6_echo", artist:"John William Waterhouse", title:"Echo and Narcissus", date:"1903", det:"Oil on canvas · Walker Art Gallery, Liverpool",
   fn:"A Royal Academy exhibition painting drawn from Ovid’s Metamorphoses.",
   sum:"Hermes’s son Pan, half man and half goat, is the god of shepherds and wild places; sudden fear in lonely country was blamed on him, giving us the word “panic.” In one story Pan pursued the nymph Echo, who rejected him and was torn apart until only her voice remained. In Ovid’s better-known version, shown here, Echo pines for Narcissus, who falls in love with his own reflection.",
   bul:["Pan: goat-legged god of the wild","Echo reduced to a voice","Ovid’s version: Narcissus and his reflection"],
   terms:[["Pan","Goat-legged son of Hermes and Dryope, god of flocks and wild places, inventor of the panpipes; source of “panic.”"],["Echo","A nymph whose body faded until only her voice remained."],["Silenus","An old, drunken satyr, tutor of Dionysus; in some accounts a son of Pan."]]},
  {type:"work", key:"h6_marsvenus", artist:"Sandro Botticelli", title:"Venus and Mars", date:"ca. 1485", det:"Tempera and oil on panel · National Gallery, London",
   fn:"A long, low panel probably set into the wall paneling or furniture of a Florentine bedroom, possibly for a wedding.",
   sum:"Aphrodite’s husband was Hephaestus, the lame smith whose forge was on the island of Lemnos, but she loved Ares. In the Odyssey, Hephaestus catches the lovers in an invisible net and calls the gods to laugh at them. Botticelli shows a calmer moral: Mars sleeps, exhausted, while Venus stays alert and little satyrs play with his armor. Love conquers war.",
   bul:["Aphrodite married to Hephaestus, loves Ares","Hephaestus’s net (Odyssey 8)","Love tames war"],
   terms:[["Lemnos","The island where Hephaestus landed when thrown from Olympus and where he kept a forge."],["Children of Ares and Aphrodite","Phobos (panic), Deimos (fear), Harmonia (harmony), and in some accounts Eros (desire)."]]},
  {type:"work", key:"h6_milo", artist:"", title:"Aphrodite of Melos (Venus de Milo)", date:"Hellenistic, ca. 150–125 BCE", det:"Marble · Louvre, Paris",
   fn:"Probably a statue set up in a gymnasium or public building on the island of Melos, where a farmer found it in 1820.",
   sum:"Aphrodite was said to have come ashore on Cyprus, and her great sanctuary stood at Paphos. Her cult has Near Eastern roots in the love-and-war goddesses Inanna, Ishtar, and Astarte, and ancient writers claimed some of her temples practiced sacred prostitution, a claim modern scholars debate. The statue’s lost arms make it impossible to know whether she held an apple, a mirror, or a shield.",
   bul:["Cult centers: Cyprus and Paphos","Roots in Inanna, Ishtar, Astarte","Arms lost; pose uncertain"],
   terms:[["Paphos","City on Cyprus with Aphrodite’s most famous sanctuary."],["Inanna/Ishtar/Astarte","Near Eastern goddesses of love and war (Sumerian, Babylonian, Phoenician) who shaped Aphrodite."]]},
  {type:"work", key:"h6_sappho", artist:"Lawrence Alma-Tadema", title:"Sappho and Alcaeus", date:"1881", det:"Oil on panel · Walters Art Museum, Baltimore",
   fn:"A Victorian history painting imagining ancient Greek life with archaeological detail.",
   sum:"Sappho, who lived on the island of Lesbos around 600 BCE, was the most celebrated female poet of antiquity, and her surviving “Hymn to Aphrodite” calls on the goddess for help in love. Alma-Tadema imagines her listening as the poet Alcaeus plays the lyre. Her poems about desire between women are why “lesbian” comes from Lesbos.",
   bul:["Sappho of Lesbos, ca. 600 BCE","Wrote a hymn to Aphrodite","Archaeologically detailed Victorian scene"],
   terms:[["Sappho","Poet of Lesbos famous for lyric poems of love, including a prayer to Aphrodite."]]},
  {type:"work", key:"h6_adonis", artist:"Titian", title:"Venus and Adonis", date:"1550s", det:"Oil on canvas · Metropolitan Museum of Art, New York",
   fn:"One of several versions of a composition first painted for Philip II; Titian’s workshop repeated it for other buyers.",
   sum:"Adonis was born from a tree: his mother Myrrha (or Smyrna), after an incestuous passion for her father, King Cinyras of Cyprus, was turned into the myrrh tree. Aphrodite loved the beautiful young hunter and begged him not to hunt, but he was killed by a boar, and anemones sprang from his blood. Titian invents the moment of her clinging plea as he pulls away. Women mourned him each year in the festival of the Adonia.",
   bul:["Adonis born from the myrrh tree","Killed by a boar; anemones from his blood","Yearly mourning festival, the Adonia"],
   terms:[["Adonis","Beautiful youth loved by Aphrodite, killed by a boar; his cult mourned him as a dying god of vegetation."],["Myrrha","Daughter of King Cinyras, turned into the myrrh tree; mother of Adonis."]]},
  {type:"work", key:"h6_pygmalion", artist:"Jean-Léon Gérôme", title:"Pygmalion and Galatea", date:"ca. 1890", det:"Oil on canvas · Metropolitan Museum of Art, New York",
   fn:"A Salon painting; Gérôme, also a sculptor, made a series on this artist-and-model theme.",
   sum:"In Ovid, the Cypriot sculptor Pygmalion carved an ivory woman so beautiful that he fell in love with her, and Aphrodite answered his prayer by bringing the statue to life. Their child was Paphos, ancestor of King Cinyras. The name Galatea for the statue was added only in the 1700s. Gérôme shows the marble turning to flesh from the top down as she bends to kiss him.",
   bul:["Statue brought to life by Aphrodite","Ovid’s Metamorphoses, Book 10","Name Galatea added much later"],
   terms:[["Pygmalion","Sculptor of Cyprus whose ivory statue Aphrodite brought to life."]]},
  {type:"work", key:"h6_hermaph", artist:"", title:"Sleeping Hermaphroditus", date:"Roman copy, 2nd century CE, of a Hellenistic original", det:"Marble; mattress added by Bernini in 1619 · Louvre, Paris",
   fn:"A Roman garden or villa sculpture designed to surprise: from the back it looks like a sleeping woman, from the front it reveals both sexes.",
   sum:"Hermaphroditus, the son of Hermes and Aphrodite, was so beautiful that the water nymph Salmacis begged the gods to join them forever, and their bodies fused into one with both male and female features. Another son of Aphrodite, Priapus (by Dionysus or Hermes), was a garden god of fertility. Bernini carved the startlingly soft mattress when the statue belonged to Cardinal Scipione Borghese.",
   bul:["Son of Hermes and Aphrodite","Fused with the nymph Salmacis","Bernini’s mattress, 1619"],
   terms:[["Hermaphroditus","Child of Hermes and Aphrodite whose body merged with the nymph Salmacis."],["Priapus","Rustic god of gardens and fertility, a son of Aphrodite."],["Eros (Cupid)","Desire, Aphrodite’s son and companion, who makes gods and humans fall in love with his arrows."]]},
  {type:"work", key:"h6_anchises", artist:"Engraving after Annibale Carracci", title:"Venus and Anchises", date:"print after a fresco of 1597–1608", det:"Engraving · Rijksmuseum, Amsterdam; fresco in the Palazzo Farnese, Rome",
   fn:"A print reproducing one scene of Carracci’s ceiling for Cardinal Odoardo Farnese; prints like this spread famous frescoes across Europe.",
   sum:"Zeus made Aphrodite herself fall for a mortal, the Trojan shepherd-prince Anchises. As the Homeric Hymn to Aphrodite tells, she visited him disguised as a girl and later revealed herself, warning him never to boast of it. Their son was Aeneas, the hero who would escape Troy and found the Roman people. Carracci’s fresco shows Anchises removing her sandal.",
   bul:["Aphrodite loves the mortal Anchises","Their son: Aeneas","Shown here in a print after the fresco"],
   terms:[["Anchises","Trojan prince loved by Aphrodite; father of Aeneas."]]},
  {type:"theme", title:"Desire as a dangerous power", img:"h6_adonis", stmt:"Aphrodite’s gifts bring joy, ruin, and transformation.",
   para:"Aphrodite and Eros can overpower anyone, even Zeus. Their stories end in transformation as often as happiness: Myrrha becomes a tree, Adonis a flower, Hermaphroditus a double body, a statue a living woman. For the Greeks, desire was a force of nature like the sea, beautiful and creative but impossible to control.",
   bul:["Even gods fall under Aphrodite’s power","Love stories end in transformation","Desire as an uncontrollable force"],
   terms:[], works:["h6_marsvenus","h6_adonis","h6_pygmalion","h6_hermaph","h6_anchises"]},
  {type:"work", key:"h6_ephesus", artist:"", title:"Artemis of Ephesus", date:"Roman copy of a Hellenistic original of the 2nd century BCE", det:"Marble and bronze · Capitoline Museums, Rome",
   fn:"A copy of the cult statue in Artemis’s great temple at Ephesus, one of the Seven Wonders of the ancient world.",
   sum:"At Ephesus, in Asia Minor, Artemis was worshipped as a mother goddess very unlike the slim huntress of mainland Greece. Her statue is covered with rows of rounded forms, long called breasts but possibly eggs or bulls’ parts, along with animals and bees, all symbols of fertility. The Ephesian Artemis shows how a Greek name could attach to an older local goddess.",
   bul:["Temple at Ephesus: a Wonder of the World","Rows of fertility symbols","Older Anatolian mother goddess"],
   terms:[["Ephesus","Greek city in Asia Minor with the vast Temple of Artemis."]]},
  {type:"work", key:"h6_niobe", artist:"Abraham Bloemaert", title:"Apollo and Diana Punishing Niobe by Killing Her Children", date:"1591", det:"Oil on canvas · Statens Museum for Kunst, Copenhagen",
   fn:"An early showpiece by the Utrecht painter, made to display his skill at twisting nude figures in the elegant Mannerist style.",
   sum:"Queen Niobe of Thebes boasted that her fourteen children made her greater than Leto, who had only two. Leto’s twins, Apollo and Artemis, shot down all of Niobe’s children with arrows. Bloemaert puts the archer gods in the clouds and fills the ground with the bodies of the young; Niobe’s grief turned her to stone on Mount Sipylus, still weeping as a spring.",
   bul:["Niobe boasts over Leto","Apollo and Artemis kill her children","Turned to weeping stone"],
   terms:[["Niobe","Theban queen whose boast against Leto cost her all her children; turned to stone."]]},
  {type:"work", key:"h6_actaeon", artist:"Titian", title:"Diana and Actaeon", date:"1556–59", det:"Oil on canvas · National Gallery, London, and National Galleries of Scotland, Edinburgh",
   fn:"One of the poesie for Philip II of Spain, now owned jointly by the two museums.",
   sum:"The hunter Actaeon stumbled on Artemis bathing with her nymphs. Furious that a man had seen her naked, she turned him into a stag, and his own hounds tore him apart. Titian shows the instant of discovery: Actaeon pulls back a curtain as the goddess snatches a cloth and glares. The stag skull on the column predicts his fate.",
   bul:["Actaeon sees Artemis bathing","Turned into a stag, killed by his dogs","Stag skull foretells his fate"],
   terms:[["Actaeon","Hunter turned into a stag by Artemis and killed by his own hounds."],["Orion","Giant hunter killed by Artemis (or her scorpion) in several versions and set among the stars."]]},
  {type:"work", key:"h6_parthenon", artist:"Iktinos and Kallikrates, with Phidias", title:"The Parthenon", date:"447–432 BCE", det:"Marble · Acropolis, Athens",
   fn:"A temple to Athena Parthenos (“the maiden”) that also served as the treasury of Athens and its empire.",
   sum:"Athens built the Parthenon after the Persian Wars, on the Acropolis the Persians had burned. Its sculptures showed Athena’s birth, her contest with Poseidon for Athens, and battles of order against chaos. Inside stood Phidias’s colossal gold-and-ivory statue of the goddess. The building became the model of Classical architecture for more than two thousand years.",
   bul:["Temple of Athena Parthenos","Built after the Persian Wars","Model of Classical architecture"],
   terms:[["Parthenon","Temple of Athena on the Athenian Acropolis, 447–432 BCE."]]},
  {type:"work", key:"h6_varvakeion", artist:"After Phidias", title:"Varvakeion Athena", date:"Roman copy, ca. 200–250 CE, of the Athena Parthenos (438 BCE)", det:"Marble · National Archaeological Museum, Athens",
   fn:"A small Roman copy of the lost cult statue that stood inside the Parthenon.",
   sum:"Phidias’s Athena Parthenos was about 40 feet tall, built of gold and ivory over a wooden core, and none of it survives. This small copy, found near the Varvakeion school in Athens, preserves its main features: a triple-crested helmet, the aegis with the Gorgon’s head, a figure of Victory in her right hand, and a shield and serpent at her side.",
   bul:["Copy of Phidias’s lost cult statue","Helmet, aegis, Victory, shield, serpent","Original: gold and ivory, ~40 ft"], terms:[]},
  {type:"work", key:"h6_snake", artist:"", title:"“Snake Goddess”", date:"Minoan, ca. 1600 BCE", det:"Faience · Heraklion Archaeological Museum, Crete",
   fn:"Found in a storage pit at the palace of Knossos, probably a cult figure or offering.",
   sum:"This small figure holds a snake in each hand, with a cat perched on her head. Some scholars see Minoan goddesses like her as distant ancestors of Athena, who also has a sacred snake and a protective role over a city. Arthur Evans’s team restored it heavily, and parts, including the head and cat, may be modern.",
   bul:["Minoan figure holding snakes","Possible ancestor of Athena’s snake","Heavily restored by Evans"], terms:[]},
  {type:"work", key:"h6_spinners", artist:"Diego Velázquez", title:"The Spinners (The Fable of Arachne)", date:"ca. 1655–60", det:"Oil on canvas · Museo del Prado, Madrid",
   fn:"Painted for a private collector in Madrid; it later entered the royal collection.",
   sum:"The Lydian weaver Arachne boasted that she wove better than Athena. In their contest, she wove the gods’ scandalous love affairs so perfectly that Athena struck her, and Arachne was turned into a spider. Velázquez puts working women spinning in the foreground and the myth in the bright room behind, where the tapestry copies Titian’s Rape of Europa.",
   bul:["Arachne challenges Athena","Turned into a spider","Myth hidden behind a workshop scene"],
   terms:[["Arachne","A weaver turned into a spider by Athena after their contest; source of “arachnid.”"]]},
  {type:"theme", title:"Goddesses of women’s lives", img:"h6_ephesus", stmt:"Each goddess governs a stage or skill of a woman’s life.",
   para:"Artemis protects girls before marriage, Aphrodite rules the attraction that leads to it, Hera guards marriage itself, Demeter motherhood and the harvest, Hestia the household fire, and Athena the weaving every woman was expected to master. Myths like Arachne’s or Niobe’s warn women against pride, just as Marsyas’s warns men.",
   bul:["Artemis: girlhood; Aphrodite: attraction","Hera and Demeter: marriage and motherhood","Athena and Hestia: weaving and home"],
   terms:[], works:["h6_ephesus","h6_niobe","h6_actaeon","h6_spinners"]}
  ]},

 /* ================= WEEK 4 · PART 1 ================= */
 {n:9, wk:4, title:"Demeter and Dionysus", sub:"Myths of fertility, mystery, and ecstasy",
  overview:{img:"h9_triptolemos", cap:["Berlin Painter","Krater with Demeter and Triptolemos","ca. 490 BCE"],
   sum:"Demeter and Dionysus are the gods of grain and wine, the two foods that kept the Greek world alive. Their myths are about loss and return: Persephone taken to the underworld and restored each spring, Dionysus born twice and arriving as a stranger. Both gods offered worshippers something the other Olympians did not, secret rites and ecstatic experiences that promised a closer bond with the divine.",
   bul:["Grain and wine: Demeter and Dionysus","Myths of loss, return, rebirth","Mystery rites and ecstatic worship"],
   terms:[["Kore","“The Maiden,” Persephone’s title; with Demeter she was worshipped as “the Two Goddesses.”"]]},
  quote:{q:"I begin to sing of rich-haired Demeter, awful goddess—of her and her trim-ankled daughter whom Aidoneus rapt away", by:"Homeric Hymn to Demeter 1–3, trans. Hugh G. Evelyn-White (1914)"},
  slides:[
  {type:"work", key:"h9_bernini", artist:"Rembrandt", title:"The Abduction of Proserpina", date:"ca. 1631", det:"Oil on panel · Gemäldegalerie, Berlin",
   fn:"Painted in Leiden early in Rembrandt’s career; it was soon in the collection of the Dutch stadholder Frederik Hendrik.",
   sum:"Hades seized Persephone while she gathered flowers and carried her off in his chariot to the underworld, with Zeus’s permission. Rembrandt makes it a struggle: she claws at Hades’s face while her companions cling to her dress, and the chariot plunges toward dark water. The painting is small, but the violence of the moment fills it.",
   bul:["Hades abducts Persephone","Her companions try to hold her back","Chariot plunges toward the underworld"],
   terms:[["Abduction of Persephone","Hades carries off Demeter’s daughter; her return for part of each year explains the seasons."]]},
  {type:"work", key:"h9_triptolemos", artist:"Berlin Painter", title:"Krater with Demeter and Triptolemos", date:"Athenian, ca. 490 BCE", det:"Red-figure volute krater · Badisches Landesmuseum, Karlsruhe",
   fn:"A large wine-mixing bowl; it was found in Sicily, an island famous for its grain and its worship of Demeter.",
   sum:"While searching for her daughter, Demeter came to Eleusis disguised as an old woman and rested by the Well of the Maiden. The royal family took her in, and in return she taught their son Triptolemus to farm. Here he sits in a winged chariot as Demeter sends him to spread grain across the world. Eleusis became the site of the Mysteries, secret rites that promised initiates a happier afterlife.",
   bul:["Demeter disguised at Eleusis","Triptolemus spreads agriculture","Eleusinian Mysteries: secret initiation"],
   terms:[["Eleusis","Town near Athens where Demeter was welcomed and where her Mysteries were held."],["Well of the Maiden","The well at Eleusis where the grieving Demeter sat in disguise."],["Eleusinian Mysteries","Secret rites for Demeter and Persephone; initiates were promised a better lot after death."],["Mystery, initiate","A mystery is a secret rite revealed only to initiates (mystai), who swore never to tell."],["Triptolemus","Eleusinian prince whom Demeter taught to farm and sent out in a winged chariot."],["Mater Dolorosa","“Sorrowful Mother,” the image of the grieving Virgin Mary, often compared to the mourning Demeter."]]},
  {type:"theme", title:"Grief that makes the seasons", img:"h9_bernini", stmt:"A mother’s grief and a daughter’s return explain the farming year.",
   para:"When Persephone vanished, Demeter stopped the crops from growing and humanity nearly starved, until Zeus ordered her return. Because Persephone had eaten pomegranate seeds in the underworld, she must go back each year. The myth ties the death and rebirth of the grain to death and hope for human beings, which is why Demeter’s Mysteries offered comfort about the afterlife.",
   bul:["Demeter’s grief stops the harvest","Pomegranate seeds bind Persephone to Hades","Crop cycle linked to hopes after death"],
   terms:[], works:["h9_bernini","h9_triptolemos"]},
  {type:"work", key:"h9_cybele", artist:"", title:"Portrait of a woman as Cybele", date:"Roman, ca. 50 CE", det:"Marble · J. Paul Getty Museum, Los Angeles",
   fn:"A portrait of a Roman woman, possibly a priestess or a member of the imperial family, shown in the guise of the goddess.",
   sum:"Cybele, the Great Mother of Phrygia in Asia Minor, sits enthroned with a lion and a tambourine. Her young consort Attis, born when the nymph Nana conceived from an almond (a fruit of the monster Agdestis), castrated himself in a frenzy and died, and her priests imitated him. Rome officially adopted Cybele in 204 BCE. Her cult, like that of Adonis, centered on a dying young god mourned by a goddess.",
   bul:["Phrygian Great Mother, with lions","Consort Attis dies and is mourned","Adopted by Rome in 204 BCE"],
   terms:[["Cybele","Great Mother goddess of Phrygia, shown with lions and a turreted crown."],["Attis","Cybele’s young consort who castrated himself and died; mourned in her rites."],["Agdestis","A double-sexed monster in Attis’s myth whose castration produced the almond tree."],["Nana","Daughter of a river god who conceived Attis from an almond."],["Cult of Adonis","Women’s yearly mourning for Aphrodite’s dead lover, a vegetation god who dies young."]]},
  {type:"work", key:"h9_bacchus", artist:"Caravaggio", title:"Bacchus", date:"ca. 1596–98", det:"Oil on canvas · Uffizi Gallery, Florence",
   fn:"Probably painted for Cardinal Francesco del Monte, Caravaggio’s early patron, and given to the Medici.",
   sum:"Dionysus was the son of Zeus and the Theban princess Semele, who was burned up when Zeus showed himself in full glory; Zeus sewed the unborn child into his thigh and gave birth to him there. Semele, brought up from Hades and made immortal, was renamed Thyone. Caravaggio paints a flushed young model in a toga, offering a glass of wine beside a bowl of overripe fruit.",
   bul:["Twice born: from Semele and from Zeus’s thigh","Semele becomes the goddess Thyone","Caravaggio’s down-to-earth god"],
   terms:[["Semele (Thyone)","Theban princess, mother of Dionysus, destroyed by Zeus’s lightning and later deified as Thyone."],["Ino (Leucothea) and Athamas","Semele’s sister and her husband, who nursed the infant Dionysus; Hera drove them mad, and Ino became the sea goddess Leucothea."]]},
  {type:"work", key:"h9_exekias", artist:"Exekias", title:"Dionysus Cup", date:"Athenian, ca. 530 BCE", det:"Black-figure kylix (interior) · Staatliche Antikensammlungen, Munich",
   fn:"A drinking cup for the symposium; as the wine was drunk, the god appeared sailing on a wine-colored sea.",
   sum:"In a Homeric Hymn, pirates kidnap Dionysus, thinking he is a prince. Vines sprout from the mast, wine floods the ship, and the god becomes a lion; the terrified sailors leap overboard and turn into dolphins. Exekias, the greatest black-figure painter, fills the whole interior with coral-red slip so the scene floats on a glowing sea.",
   bul:["Pirates kidnap Dionysus","Vines from the mast, sailors become dolphins","Coral-red interior turns the cup into a sea"], terms:[],
   quote:{q:"And all at once a vine spread out both ways along the top of the sail with many clusters hanging down from it", by:"Homeric Hymn to Dionysus 38–40, trans. Evelyn-White"}},
  {type:"work", key:"h9_maenad", artist:"Nicolas Poussin", title:"A Bacchanalian Revel before a Term", date:"ca. 1632–33", det:"Oil on canvas · National Gallery, London",
   fn:"Painted in Rome, where Poussin spent most of his career; his bacchanals revived the ancient wine feast in a cool, frieze-like style learned from Roman reliefs.",
   sum:"Maenads (“mad women”), also called Bacchae, were the female followers of Dionysus who roamed the mountains in ecstatic dances. Poussin shows them in a ring dance with satyrs before a garlanded statue of Pan, wine and fruit spilling around them. The rites could end in sparagmos, tearing a living animal apart.",
   bul:["Maenads: Dionysus’s female followers","Dance, wine, and the god Pan","Ecstasy in the countryside"],
   terms:[["Bacchae, Thyiades, Maenads","Names for the frenzied women who worshipped Dionysus."],["Thyrsus","A fennel staff topped with a pinecone and ivy, carried by Dionysus’s followers."],["Enthousiasmos","Being filled with the god (“en-theos”), the root of “enthusiasm.”"],["Ekstasis","“Standing outside oneself,” the ecstatic state Dionysus’s rites produced."]]},
  {type:"work", key:"h9_midas", artist:"Nicolas Poussin", title:"Midas and Bacchus", date:"ca. 1624", det:"Oil on canvas · Alte Pinakothek, Munich",
   fn:"An early painting from Poussin’s first years in Rome; it later belonged to the Bavarian elector Max Emanuel.",
   sum:"King Midas of Phrygia, in some versions a son of Cybele, sheltered Dionysus’s drunken tutor Silenus, and the grateful god granted him a wish. Midas asked that everything he touched turn to gold, then nearly starved. Poussin shows Midas kneeling to thank Bacchus while satyrs and Silenus sleep off the wine; Midas was cured by bathing in the river Pactolus in Lydia, whose sands turned golden.",
   bul:["Midas hosts Silenus","The golden touch","Cured in the river Pactolus"],
   terms:[["Midas","King of Phrygia granted the golden touch by Dionysus."],["Satyrs","Male followers of Dionysus, part man and part horse or goat, lovers of wine and mischief."],["Lydia","Kingdom in western Asia Minor, rich in gold from the river Pactolus."]]},
  {type:"work", key:"h9_pentheus", artist:"", title:"The Death of Pentheus", date:"Roman, 62–79 CE", det:"Wall painting · House of the Vettii, Pompeii",
   fn:"Part of the painted decoration of a dining room in a wealthy freedmen’s house, where mythological scenes impressed guests.",
   sum:"King Pentheus of Thebes, Dionysus’s cousin, refused to accept the new god and tried to suppress his rites. In Euripides’ tragedy the Bacchae, Dionysus lures him to spy on the maenads, who in their frenzy mistake him for a beast and tear him apart, led by his own mother, Agave. The painting shows the women closing in as Pentheus falls.",
   bul:["Pentheus rejects Dionysus","Torn apart by the maenads","Euripides’ Bacchae"],
   terms:[["Pentheus","King of Thebes torn apart by maenads, including his mother, for rejecting Dionysus."]]},
  {type:"theme", title:"The god who breaks boundaries", img:"h9_maenad", stmt:"Dionysus dissolves the lines between human and animal, sane and mad, self and god.",
   para:"Dionysus arrives as a foreigner and is resisted by kings like Pentheus, who are destroyed for refusing him. His gifts, wine, ecstasy, and theater, let worshippers step outside ordinary life for a time. The myths warn that this power must be honored in its place: welcomed, it brings joy; denied, it explodes.",
   bul:["Foreign god resisted and then accepted","Wine and ecstasy loosen ordinary limits","Denying him brings destruction"],
   terms:[], works:["h9_bacchus","h9_exekias","h9_maenad","h9_pentheus"]},
  {type:"work", key:"h9_andrians", artist:"Titian", title:"The Bacchanal of the Andrians", date:"1523–26", det:"Oil on canvas · Museo del Prado, Madrid",
   fn:"Painted for Alfonso d’Este, Duke of Ferrara, as a companion to Bacchus and Ariadne in his private study.",
   sum:"Based on an ancient description of a painting by Philostratus, the scene shows the people of the island of Andros, where a river ran with wine thanks to Dionysus. Dancers, drinkers, and a sleeping nude enjoy a festival of the god. A sheet of music in the foreground reads, in French, that whoever drinks and does not drink again does not know what drinking is.",
   bul:["Island of Andros with a river of wine","Based on an ancient text by Philostratus","Painted for the Duke of Ferrara"],
   terms:[["Bacchanal","A festival or revel in honor of Bacchus; Rome’s Bacchanalia were banned in 186 BCE."]]},
  {type:"work", key:"h9_epidaurus", artist:"Attributed to Polykleitos the Younger", title:"Theater of Epidaurus", date:"ca. 340–300 BCE", det:"Limestone · Epidaurus, Greece",
   fn:"A theater in the sanctuary of the healing god Asclepius, famous for its acoustics and still used for performances.",
   sum:"Greek drama grew out of festivals for Dionysus, and in Athens tragedies and comedies were performed at his festival, the City Dionysia. A theater had a curved seating area (theatron), a round dancing floor for the chorus (orchestra), and a stage building behind (skene). Epidaurus, the best preserved, holds about 13,000 people.",
   bul:["Drama born in Dionysus’s festivals","Theatron, orchestra, skene","Best-preserved Greek theater"],
   terms:[["Theatron","“Viewing place,” the curved seating of a Greek theater."],["Orchestra","“Dancing place,” the circular floor where the chorus performed."],["Cult of Dionysus","Worship through wine, ecstatic dance, sacrifice, and drama."]]}
  ]},

 /* ================= WEEK 4 · PART 2 ================= */
 {n:10, wk:4, title:"Myths of Death", sub:"The underworld and its visitors",
  overview:{img:"h10_patinir", cap:["Joachim Patinir","Charon Crossing the Styx","ca. 1520–24"],
   sum:"For most Greeks, the dead became weak, shadowy images of themselves in the gloomy realm of Hades, whatever kind of life they had lived. Only a few great sinners were singled out for punishment and a few favored heroes for paradise. Over the centuries, mystery cults, philosophers, and Roman poets turned this shadowland into a place of judgment and reward, a picture that passed into Christian ideas of hell and heaven.",
   bul:["Hades: shadowy afterlife for most","Punishment for a few, paradise for fewer","Later writers add judgment and reward"],
   terms:[["Soul (psyche, anima)","The breath or life-spirit that leaves the body at death; psyche in Greek, anima in Latin."],["Hades","“The unseen one,” the god and his realm; the Romans called the god Pluto, “the enricher.”"],["Orcus","A Roman name for the underworld and its god, “the place that confines.”"],["Eidolon","The image or shade of a dead person, a thin copy of the living."],["Anthesteria","Athenian spring festival of new wine when the spirits of the dead were believed to roam, sometimes compared to Halloween."]]},
  quote:{q:"The gates of hell are open night and day; Smooth the descent, and easy is the way", by:"Virgil, Aeneid 6, trans. John Dryden (1697)"},
  slides:[
  {type:"work", key:"h10_charon", artist:"", title:"White-ground lekythos with Charon", date:"Athenian, later 5th century BCE", det:"Terracotta · Museum für Kunst und Gewerbe, Hamburg",
   fn:"An oil flask painted for the dead: lekythoi with white grounds were left at graves and buried with the deceased.",
   sum:"Hermes, as guide of souls, led the dead to the river, where the ferryman Charon rowed them across for the price of a coin. Families placed an obol in the mouth of the dead for the fare. White-ground lekythoi, painted in delicate colors on a chalky white surface, show these last journeys and quiet farewells at the tomb.",
   bul:["Hermes leads, Charon ferries","Coin for the fare","Grave offerings for the dead"],
   terms:[["Psychopompos","“Guide of souls,” Hermes’s role in leading the dead."],["Charon","The ferryman who carries the dead across the river of the underworld."],["Lekythos","A narrow oil flask; white-ground lekythoi were funeral offerings."]]},
  {type:"work", key:"h10_patinir", artist:"Joachim Patinir", title:"Charon Crossing the Styx", date:"ca. 1520–24", det:"Oil on panel · Museo del Prado, Madrid",
   fn:"A landscape painting whose first owner is not recorded; it later belonged to Philip II of Spain.",
   sum:"Patinir places Charon’s boat in the middle of a vast river between paradise on the left, with angels, and hell on the right, guarded by the three-headed dog Cerberus. The small soul in the boat looks toward hell. The painting mixes the classical ferryman with the Christian choice between salvation and damnation.",
   bul:["Charon’s boat between two shores","Paradise vs. hell, guarded by Cerberus","Classical myth meets Christian judgment"],
   terms:[["Styx and Acheron","Rivers of the underworld; the Styx was the river of oaths, the Acheron the river of woe."],["Cerberus","Many-headed hound guarding the gates of Hades."]]},
  {type:"work", key:"h10_tiresias", artist:"Henry Fuseli", title:"Tiresias Appears to Ulysses during the Sacrifice", date:"1780–85", det:"Watercolor · Albertina, Vienna",
   fn:"A large watercolor by the Swiss-born painter, who settled in London and specialized in dramatic scenes from Homer, Shakespeare, and Milton.",
   sum:"In Odyssey 11, the witch Circe sends Odysseus to the edge of the world, the land of the Cimmerians, to consult the dead seer Tiresias. He digs a pit and pours in sacrificial blood, and the shades flock to drink it. Fuseli shows the blind prophet rising in a cloud of shades while Odysseus crouches by the pit, sword drawn. Odysseus’s visit is an act of necromancy, calling up the dead to learn the future.",
   bul:["Circe sends Odysseus to the dead","Blood offering draws the shades","Tiresias foretells his journey home"],
   terms:[["Tiresias","The blind Theban prophet who keeps his wisdom even in death."],["Circe","Witch-goddess who sends Odysseus to consult the dead."],["Necromancer","One who calls up the dead to ask about the future."],["Cimmerians","A people living in perpetual mist at the edge of the world, near the entrance to Hades."]]},
  {type:"theme", title:"A gloomy afterlife for almost everyone", img:"h10_charon", stmt:"Homer’s dead envy the living.",
   para:"In the Odyssey, the shades Odysseus meets teach hard lessons. Agamemnon, murdered by his wife, warns against trusting women; Achilles says he would rather be a poor laborer on earth than king of all the dead; Ajax, still angry over a lost contest, refuses to speak. King Minos judges disputes, and Orion still hunts. Fame on earth was the only real immortality.",
   bul:["Agamemnon: betrayal","Achilles: life above all","Ajax: anger outlasts death"],
   terms:[["Lessons of the dead","Agamemnon, Achilles, Ajax, King Minos, and Orion appear in Odyssey 11, each showing what death does to a hero."]],
   works:["h10_tiresias","h10_charon"]},
  {type:"work", key:"h10_sisyphus", artist:"Titian", title:"Sisyphus", date:"1548–49", det:"Oil on canvas · Museo del Prado, Madrid",
   fn:"One of four paintings of the great sinners (the “Furies”) made for Mary of Hungary’s palace at Binche, as a warning to rebels.",
   sum:"A few sinners earned eternal punishment in Tartarus. Sisyphus, who cheated death, pushes a boulder uphill forever; Tantalus stands in water that recedes when he bends to drink, beneath fruit he cannot reach; Ixion, who tried to seduce Hera, spins on a fiery wheel; and Tityus has his liver eaten by vultures. Titian’s Sisyphus bends under a rock that seems to crush him.",
   bul:["Sisyphus: endless boulder","Tantalus, Ixion, Tityus","Painted as warnings to rebels"],
   terms:[["Tartarus","The deepest part of the underworld, where the worst sinners are punished."],["Tantalus","Tormented with hunger and thirst, food and water always out of reach; source of “tantalize.”"],["Sisyphus","King who cheated death and must push a boulder uphill forever."],["Ixion","Bound to a spinning wheel for trying to seduce Hera; from his union with a cloud came the Centaurs."],["Centaurs","Half-human, half-horse creatures, descendants of Ixion."]]},
  {type:"theme", title:"Punishments that fit the crime", img:"h10_map", stmt:"The great sinners all tried to take what belonged to the gods.",
   para:"Each famous sinner offended the gods directly: Tantalus tested them by serving his son as a meal, Ixion lusted after Hera, Sisyphus tricked Death itself. Their punishments are endless repetitions or frustrations, making the crime visible forever. The idea of matching punishment to sin lasted into Dante’s Inferno.",
   bul:["Sinners offended the gods themselves","Endless, repeated torments","Model for Dante’s hell"],
   terms:[], works:["h10_sisyphus","h10_map"]},
  {type:"work", key:"h10_orpheusrel", artist:"", title:"Orpheus, Eurydice, and Hermes", date:"Roman copy, 1st century BCE, of an Athenian relief of ca. 410 BCE", det:"Marble · Louvre, Paris",
   fn:"A Roman copy of a famous Athenian relief, made for a collector who wanted a celebrated Greek work.",
   sum:"The poet Orpheus, whose music could move stones, went down to Hades to bring back his wife Eurydice, who had died from a snakebite. Charmed by his song, the gods let her go on one condition: he must not look back. He turned at the last moment, and she was lost. The relief shows the farewell, as Hermes gently takes her wrist to lead her back.",
   bul:["Orpheus charms the underworld","He looks back and loses Eurydice","Hermes leads her away"],
   terms:[["Orpheus and Eurydice","The singer who almost rescued his wife from death but looked back too soon."],["Orphism","A religious movement claiming Orpheus as founder, teaching purity and the soul’s rebirth."],["Metempsychosis","The transmigration of the soul into a new body after death, taught by Orphics and Pythagoreans."]]},
  {type:"work", key:"h10_corot", artist:"Jean-Baptiste-Camille Corot", title:"Orpheus Leading Eurydice from the Underworld", date:"1861", det:"Oil on canvas · Museum of Fine Arts, Houston",
   fn:"A large Salon landscape with a mythological subject, made for public exhibition.",
   sum:"Corot imagines the underworld as a misty, silvery grove, closer to the Elysian Fields than to a place of torment. Orpheus raises his lyre and leads Eurydice by the hand, not yet looking back. In the Greek imagination most souls drifted through dim Asphodel Meadows, while a lucky few heroes went to Elysium, a paradise of endless calm.",
   bul:["Underworld as a misty grove","Orpheus not yet looking back","Asphodel Meadows vs. Elysium"],
   terms:[["Asphodel Meadows","The gray plain where ordinary souls wander."],["Elysium (Elysian Fields)","The paradise reserved for heroes and the favored of the gods."]]},
  {type:"work", key:"h10_map", artist:"Sandro Botticelli", title:"The Map of Hell", date:"ca. 1480–95", det:"Ink and color on parchment · Vatican Library",
   fn:"Part of a lavish illustrated manuscript of Dante’s Divine Comedy, probably for Lorenzo di Pierfrancesco de’ Medici.",
   sum:"Plato’s Republic ends with the Myth of Er, a soldier who returns from death to describe souls being judged, rewarded, punished, and choosing new lives. Ideas like these flowed into Christian visions of the afterlife. Dante’s Inferno arranges hell as a funnel of nine circles, staffed by classical figures such as Charon, Minos, and Cerberus, which Botticelli maps from top to bottom.",
   bul:["Plato’s Myth of Er: judgment and rebirth","Dante: hell as nine circles","Classical guardians in a Christian hell"],
   terms:[["Myth of Er","Story in Plato’s Republic of a man who returns from death to describe judgment and reincarnation."],["Inferno, Purgatory, Paradise","The three parts of Dante’s Divine Comedy: hell, purgatory, and heaven."]]},
  {type:"work", key:"h10_brueghel", artist:"Jan Brueghel the Younger", title:"Aeneas and the Sibyl in the Underworld", date:"1630s", det:"Oil on copper · Metropolitan Museum of Art, New York",
   fn:"A small, jewel-like painting on copper, a support often used for collectors’ cabinet pictures.",
   sum:"In Book 6 of Virgil’s Aeneid, the Cumaean Sibyl leads Aeneas down through a cave near Lake Avernus to visit his dead father, Anchises. They cross the Acheron in Charon’s boat and pass the places of punishment before reaching Elysium, where Anchises shows his son the souls of future Romans. Brueghel crowds the dark landscape with fires, monsters, and tiny tormented figures.",
   bul:["Aeneid 6: descent at Lake Avernus","Guided by the Cumaean Sibyl","Anchises shows Rome’s future"],
   terms:[["Lake Avernus","Volcanic lake near Naples believed to be an entrance to the underworld."],["Cumaean Sibyl","Prophetess of Apollo at Cumae who guides Aeneas."],["Anchises","Aeneas’s father, met in Elysium."]]},
  {type:"theme", title:"From shadows to judgment", img:"h10_orpheusrel", stmt:"The afterlife becomes moral over time.",
   para:"Homer’s underworld is mostly the same for everyone. Mystery cults promised initiates a better fate, Orphics and Plato added judgment and reincarnation, and Virgil arranged the dead by their deeds and gave Rome a destiny. Dante then built hell, purgatory, and heaven from these classical pieces, and artists kept painting the result for centuries.",
   bul:["Homer: same fate for nearly all","Mysteries, Orphics, Plato: reward and rebirth","Virgil and Dante: an ordered moral world"],
   terms:[], works:["h10_orpheusrel","h10_map","h10_brueghel"]}
  ]}
);
